package com.securebiz.securitydata.repository;import com.securebiz.securitydata.api.SecurityDataDtos.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Repository;import java.sql.*;import java.time.Instant;import java.util.*;
@Repository public class SecurityEventRepository{private final JdbcClient jdbc;public SecurityEventRepository(JdbcClient jdbc){this.jdbc=jdbc;}public void create(UUID user,String type,String module,String severity,String indicators,String context,String dedup){jdbc.sql("INSERT INTO security_events(id,user_id,event_type,module,severity,indicators,context,deduplication_key) VALUES(:id,:user,:type,:module,:severity,CAST(:indicators AS jsonb),CAST(:context AS jsonb),:dedup) ON CONFLICT(deduplication_key) WHERE deduplication_key IS NOT NULL DO NOTHING").param("id",UUID.randomUUID()).param("user",user).param("type",type).param("module",module).param("severity",severity).param("indicators",indicators).param("context",context).param("dedup",dedup).update();}public List<SecurityEventResponse>events(int size,long offset){return jdbc.sql("SELECT * FROM security_events ORDER BY occurred_at DESC LIMIT :size OFFSET :offset").param("size",size).param("offset",offset).query((r,n)->new SecurityEventResponse(r.getObject("id",UUID.class),r.getObject("user_id",UUID.class),r.getString("event_type"),r.getString("module"),r.getString("severity"),r.getTimestamp("occurred_at").toInstant(),r.getString("indicators"),r.getString("context"))).list();}public long countEvents(){return count("SELECT count(*) FROM security_events");}public List<UserSecurityProfile>profiles(int size,long offset){return jdbc.sql("SELECT * FROM user_security_profiles ORDER BY denied_30d DESC,events_30d DESC,username LIMIT :size OFFSET :offset").param("size",size).param("offset",offset).query(this::mapProfile).list();}public long countProfiles(){return count("SELECT count(*) FROM user_security_profiles");}public Optional<UserSecurityProfile>profile(UUID id){return jdbc.sql("SELECT * FROM user_security_profiles WHERE user_id=:id").param("id",id).query(this::mapProfile).optional();}
public SecurityOverview overview(int days){long alertsToday=count("SELECT count(*) FROM security_alerts WHERE created_at>=date_trunc('day',now())");long critical=count("SELECT count(*) FROM security_alerts WHERE severity='CRITICAL' AND status IN('OPEN','INVESTIGATING')");long highRisk=count("SELECT count(*) FROM (SELECT DISTINCT ON(user_id) user_id,risk_score FROM risk_assessments ORDER BY user_id,created_at DESC) latest WHERE risk_score>=70");long denied=jdbc.sql("SELECT count(*) FROM activity_logs WHERE result='DENIED' AND occurred_at>=now()-(:days||' days')::interval").param("days",days).query(Long.class).single();var alertTrend=trend("SELECT d::date label,count(a.id)::double precision value FROM generate_series(current_date-(:days-1),current_date,interval '1 day') d LEFT JOIN security_alerts a ON a.created_at>=d AND a.created_at<d+interval '1 day' GROUP BY d ORDER BY d",days);var riskTrend=trend("SELECT d::date label,COALESCE(avg(r.risk_score),0)::double precision value FROM generate_series(current_date-(:days-1),current_date,interval '1 day') d LEFT JOIN risk_assessments r ON r.created_at>=d AND r.created_at<d+interval '1 day' GROUP BY d ORDER BY d",days);var modules=jdbc.sql("""
SELECT COALESCE(source.module,'unknown') module,count(*) count FROM security_alerts a
JOIN risk_assessments r ON r.id=a.risk_assessment_id JOIN anomaly_predictions p ON p.id=r.prediction_id
JOIN feature_snapshots f ON f.id=p.feature_snapshot_id
LEFT JOIN LATERAL(SELECT l.module FROM activity_logs l WHERE l.user_id=f.user_id AND l.occurred_at>=f.window_start AND l.occurred_at<f.window_end GROUP BY l.module ORDER BY count(*) DESC,l.module LIMIT 1)source ON true
WHERE a.created_at>=now()-(:days||' days')::interval GROUP BY source.module ORDER BY count(*) DESC
""").param("days",days).query((row,n)->new SecurityModuleCount(row.getString("module"),row.getLong("count"))).list();return new SecurityOverview(alertsToday,critical,highRisk,denied,alertTrend,riskTrend,modules);}
public Optional<UserSecurityProfileDetail>profileDetail(UUID id){var profile=profile(id);if(profile.isEmpty())return Optional.empty();var risk=jdbc.sql("SELECT created_at,risk_score,severity,baseline_scope,baseline_sample_size FROM risk_assessments WHERE user_id=:id ORDER BY created_at DESC LIMIT 30").param("id",id).query((r,n)->new UserRiskPoint(r.getTimestamp("created_at").toInstant(),r.getDouble("risk_score"),r.getString("severity"),r.getString("baseline_scope"),r.getInt("baseline_sample_size"))).list();var alerts=jdbc.sql("SELECT id,status,severity,risk_score,created_at FROM security_alerts WHERE user_id=:id ORDER BY created_at DESC LIMIT 30").param("id",id).query((r,n)->new UserAlertSummary(r.getObject("id",UUID.class),r.getString("status"),r.getString("severity"),r.getDouble("risk_score"),r.getTimestamp("created_at").toInstant())).list();var activity=jdbc.sql("SELECT id,occurred_at,action,module,result FROM activity_logs WHERE user_id=:id ORDER BY occurred_at DESC LIMIT 100").param("id",id).query((r,n)->new UserActivitySummary(r.getObject("id",UUID.class),r.getTimestamp("occurred_at").toInstant(),r.getString("action"),r.getString("module"),r.getString("result"))).list();String baseline=jdbc.sql("SELECT baseline::text FROM risk_assessments WHERE user_id=:id ORDER BY created_at DESC LIMIT 1").param("id",id).query(String.class).optional().orElse("{}");String recent=jdbc.sql("SELECT features::text FROM feature_snapshots WHERE user_id=:id ORDER BY window_end DESC LIMIT 1").param("id",id).query(String.class).optional().orElse("{}");Double current=risk.isEmpty()?null:risk.getFirst().riskScore();return Optional.of(new UserSecurityProfileDetail(profile.get(),current,baseline,recent,risk,alerts,activity));}
private long count(String sql){return jdbc.sql(sql).query(Long.class).single();}private List<SecurityTrendPoint>trend(String sql,int days){return jdbc.sql(sql).param("days",days).query((row,n)->new SecurityTrendPoint(row.getDate("label").toString(),row.getDouble("value"))).list();}private UserSecurityProfile mapProfile(ResultSet r,int n)throws SQLException{return new UserSecurityProfile(r.getObject("user_id",UUID.class),r.getString("username"),r.getObject("employee_id",UUID.class),r.getObject("department_id",UUID.class),r.getLong("actions_30d"),r.getLong("denied_30d"),r.getLong("events_30d"),instant(r,"last_activity_at"),instant(r,"last_security_event_at"));}private Instant instant(ResultSet r,String name)throws SQLException{return r.getTimestamp(name)==null?null:r.getTimestamp(name).toInstant();}}
